import{_ as i,C as r,o as n,c as s,j as t,a as e,E as o,aj as c}from"./chunks/framework.m090XgxO.js";const q=JSON.parse('{"title":"Kbd","description":"","frontmatter":{},"headers":[],"relativePath":"components/kbd.md","filePath":"components/kbd.md","lastUpdated":1789206102000}'),h={name:"components/kbd.md"},b={id:"kbd",tabindex:"-1"};function p(u,d,k,f,m,x){const l=r("Badge"),a=r("XhDemo");return n(),s("div",null,[t("h1",b,[d[0]||(d[0]=e("Kbd ",-1)),o(l,{type:"info",text:"键帽"}),d[1]||(d[1]=e()),d[2]||(d[2]=t("a",{class:"header-anchor",href:"#kbd","aria-label":'Permalink to "Kbd <Badge type="info" text="键帽" />"'},"​",-1))]),d[3]||(d[3]=c('<p>显示一枚语义键帽，不注册任何键盘监听。<code>Mod</code> 会按平台写成 Mac 的 ⌘ 或其他平台的 Ctrl；要显示完整组合用<a href="./kbd-group">键帽组</a>，要注册动作另用<a href="./hotkeys">快捷键</a>。</p><div class="xh-resource-links"><a href="https://github.com/XiHanFun/XiHan.UI/tree/dev/ui/packages/engine/headless/src/kbd" target="_blank" rel="noreferrer">Headless</a><a href="https://github.com/XiHanFun/XiHan.UI/blob/dev/ui/packages/design/styles/css/kbd.css" target="_blank" rel="noreferrer">Styles</a><a href="https://github.com/XiHanFun/XiHan.UI/tree/dev/ui/packages/adapters/vue/src/components/kbd" target="_blank" rel="noreferrer">Vue</a><a href="https://github.com/XiHanFun/XiHan.UI/tree/dev/ui/packages/adapters/react/src/components/kbd" target="_blank" rel="noreferrer">React</a><a href="https://github.com/XiHanFun/XiHan.UI/blob/dev/ui/packages/adapters/web-components/src/elements/kbd.ts" target="_blank" rel="noreferrer">Web Components</a></div><h2 id="用法" tabindex="-1">用法 <a class="header-anchor" href="#用法" aria-label="Permalink to &quot;用法&quot;">​</a></h2><p>单枚原生 kbd，只显示键名，不注册快捷键</p>',4)),o(a,{src:"kbd/01-basic"}),d[4]||(d[4]=t("h2",{id:"示例",tabindex:"-1"},[e("示例 "),t("a",{class:"header-anchor",href:"#示例","aria-label":'Permalink to "示例"'},"​")],-1)),d[5]||(d[5]=t("h3",{id:"尺寸",tabindex:"-1"},[e("尺寸 "),t("a",{class:"header-anchor",href:"#尺寸","aria-label":'Permalink to "尺寸"'},"​")],-1)),d[6]||(d[6]=t("p",null,"三档同时调整键帽字号与行内留白",-1)),o(a,{src:"kbd/02-size"}),d[7]||(d[7]=t("h3",{id:"禁用",tabindex:"-1"},[e("禁用 "),t("a",{class:"header-anchor",href:"#禁用","aria-label":'Permalink to "禁用"'},"​")],-1)),d[8]||(d[8]=t("p",null,"只表达对应动作不可用，不会降低整段文字的不透明度",-1)),o(a,{src:"kbd/03-disabled"}),d[9]||(d[9]=t("h3",{id:"真实按下",tabindex:"-1"},[e("真实按下 "),t("a",{class:"header-anchor",href:"#真实按下","aria-label":'Permalink to "真实按下"'},"​")],-1)),d[10]||(d[10]=t("p",null,"键帽只在可交互 owner 真正 active 时轻压",-1)),o(a,{src:"kbd/04-pressed"}),d[11]||(d[11]=c('<h2 id="设计指引" tabindex="-1">设计指引 <a class="header-anchor" href="#设计指引" aria-label="Permalink to &quot;设计指引&quot;">​</a></h2><h3 id="何时使用" tabindex="-1">何时使用 <a class="header-anchor" href="#何时使用" aria-label="Permalink to &quot;何时使用&quot;">​</a></h3><ul><li>在说明文字里表示一枚键。</li><li>需要单独控制一枚键帽的尺寸、禁用或真实按下反馈。</li></ul><h3 id="何时不用" tabindex="-1">何时不用 <a class="header-anchor" href="#何时不用" aria-label="Permalink to &quot;何时不用&quot;">​</a></h3><ul><li>显示完整快捷键组合：用<a href="./kbd-group">键帽组</a>，让读屏只念一次整组。</li><li>注册快捷键动作：用<a href="./hotkeys">快捷键</a>，不要给纯展示节点安装全局监听。</li><li>显示代码或命令文本：用<a href="./code-view">代码视图</a>。</li></ul><h3 id="特性" tabindex="-1">特性 <a class="header-anchor" href="#特性" aria-label="Permalink to &quot;特性&quot;">​</a></h3><ul><li>使用原生 <code>kbd</code> 语义，平台格式化唯一事实源在 Headless。</li><li><code>pressed</code> 只投影作者已知的真实激活事实；组件不会自己监听键盘，也不会默认制造按下态。</li><li>M1 实体小表面使用 1px 边、顶部高光和底部 contact shadow；按下时轻压并撤掉海拔。</li><li>compact 密度、三尺寸、RTL、forced-colors 和 200% 缩放均保持键名清楚。</li></ul><h2 id="产物" tabindex="-1">产物 <a class="header-anchor" href="#产物" aria-label="Permalink to &quot;产物&quot;">​</a></h2><table tabindex="0"><thead><tr><th>层</th><th>值</th></tr></thead><tbody><tr><td>自定义元素</td><td><code>&lt;xh-kbd&gt;</code></td></tr><tr><td>Vue 组件</td><td><code>XhKbd</code></td></tr><tr><td>状态机</td><td>无，<code>connect</code> 直接由 props 算属性</td></tr><tr><td>皮肤</td><td><code>@xihan-ui/styles/kbd.css</code></td></tr></tbody></table><h2 id="解剖" tabindex="-1">解剖 <a class="header-anchor" href="#解剖" aria-label="Permalink to &quot;解剖&quot;">​</a></h2><p>部件名即 <code>data-part</code> 属性值，也是皮肤的选择器。加粗的是必备部件，不渲染它组件不工作（Web Components 适配器会在诊断通道上报 <code>wc.missing-part</code>）。</p><p><code>data-scope=&quot;kbd&quot;</code>：<strong><code>root</code></strong></p><h2 id="props" tabindex="-1">Props <a class="header-anchor" href="#props" aria-label="Permalink to &quot;Props&quot;">​</a></h2><table tabindex="0"><thead><tr><th>属性</th><th>类型</th><th>必填</th><th>说明</th></tr></thead><tbody><tr><td><code>disabled</code></td><td><code>boolean</code></td><td></td><td>这枚键所提示的动作是否不可用。</td></tr><tr><td><code>platform</code></td><td><code>HotkeysPlatform</code></td><td></td><td>平台写法；auto 在适配器测出平台前按 other。</td></tr><tr><td><code>pressed</code></td><td><code>boolean</code></td><td></td><td>这枚键是否正在被真实动作激活；纯展示默认静止。</td></tr><tr><td><code>size</code></td><td><code>Size</code></td><td></td><td>尺寸：sm / md / lg。</td></tr><tr><td><code>translations</code></td><td><code>Partial&lt;KbdTranslations&gt;</code></td><td></td><td>读屏键名覆盖。</td></tr><tr><td><code>value</code></td><td><code>string</code></td><td>是</td><td>一枚键的声明，例如 Mod、Shift、Esc 或 S。</td></tr></tbody></table><h2 id="connect-api" tabindex="-1">connect API <a class="header-anchor" href="#connect-api" aria-label="Permalink to &quot;connect API&quot;">​</a></h2><p><code>connect</code> 产出的对象。<code>getXxxProps()</code> 铺到对应部件的宿主元素上，其余是可读状态与操作入口。</p><table tabindex="0"><thead><tr><th>成员</th><th>类型</th><th>说明</th></tr></thead><tbody><tr><td><code>segment</code></td><td><code>HotkeySegment</code></td><td>归一化后的键。</td></tr><tr><td><code>label</code></td><td><code>string</code></td><td>键帽可见文本。</td></tr><tr><td><code>platform</code></td><td><code>HotkeysResolvedPlatform</code></td><td>实际采用的平台写法。</td></tr><tr><td><code>getRootProps</code></td><td><code>() =&gt; T[&#39;element&#39;]</code></td><td></td></tr></tbody></table><h2 id="键盘" tabindex="-1">键盘 <a class="header-anchor" href="#键盘" aria-label="Permalink to &quot;键盘&quot;">​</a></h2><p>规格出处：<a href="https://html.spec.whatwg.org/multipage/text-level-semantics.html#the-kbd-element" target="_blank" rel="noreferrer">W3C APG</a></p><p>无键盘交互（不接收焦点，或焦点行为完全由原生元素提供）。</p><h2 id="无障碍" tabindex="-1">无障碍 <a class="header-anchor" href="#无障碍" aria-label="Permalink to &quot;无障碍&quot;">​</a></h2><p>下面这些由 <code>connect</code> 铺到部件上，作者不必自己写；重复写反而会覆盖掉正确值。</p><table tabindex="0"><thead><tr><th>部件</th><th>属性</th><th>值</th></tr></thead><tbody><tr><td><code>root</code></td><td><code>aria-label</code></td><td>props.translations?.keyName?.(segment.key)</td></tr></tbody></table><ul><li>符号键帽通过 <code>aria-label</code> 使用可读键名；例如 ⌘ 念作 Command。</li><li>单枚键帽可独立进入无障碍树；在 KbdGroup 内由组级名称统一朗读，子键帽会被隐藏。</li></ul><h2 id="样式" tabindex="-1">样式 <a class="header-anchor" href="#样式" aria-label="Permalink to &quot;样式&quot;">​</a></h2><p>默认皮肤 <code>@xihan-ui/styles/kbd.css</code> 按部件选择：<code>[data-scope=&quot;kbd&quot;][data-part=&quot;root&quot;]</code>。它落在 <code>xihan.components</code> 层；业务样式不写进 <code>@layer</code> 即高于全部库层，要按层压过来就写进 <code>xihan.overrides</code>。</p><p><code>forced-colors: active</code> 下另有一套规则：颜色交给系统，边框与状态标记改用系统色关键字。</p><h2 id="数据属性" tabindex="-1">数据属性 <a class="header-anchor" href="#数据属性" aria-label="Permalink to &quot;数据属性&quot;">​</a></h2><p>由 <code>connect</code> 产出并铺到部件上，皮肤与测试都据此选择；<code>data-disabled</code> 这类无值属性在条件不成立时整个不出现。</p><table tabindex="0"><thead><tr><th>部件</th><th>属性</th><th>值</th></tr></thead><tbody><tr><td><code>root</code></td><td><code>data-disabled</code></td><td>&#39;&#39;（条件成立时才出现）</td></tr><tr><td><code>root</code></td><td><code>data-modifier</code></td><td>&#39;&#39;（条件成立时才出现）</td></tr><tr><td><code>root</code></td><td><code>data-platform</code></td><td>resolveHotkeysPlatform(props.platform)</td></tr><tr><td><code>root</code></td><td><code>data-pressed</code></td><td>&#39;&#39;（条件成立时才出现）</td></tr><tr><td><code>root</code></td><td><code>data-size</code></td><td>props.size</td></tr></tbody></table><h2 id="css-变量" tabindex="-1">CSS 变量 <a class="header-anchor" href="#css-变量" aria-label="Permalink to &quot;CSS 变量&quot;">​</a></h2><p>本组件公开覆盖槽由独立皮肤的实际消费位生成；缺省来源、作用部件和状态均与 CSS 同源。</p><table tabindex="0"><thead><tr><th>变量</th><th>部件</th><th>CSS 属性</th><th>状态</th><th>缺省来源</th><th>说明</th></tr></thead><tbody><tr><td><code>--xh-kbd-bg</code></td><td><code>root</code></td><td><code>background</code></td><td><code>default</code></td><td><code>--xh-material-soft-bg</code></td><td>kbd 的 root 部件 background 覆盖槽。</td></tr><tr><td><code>--xh-kbd-bg-disabled</code></td><td><code>root</code></td><td><code>background</code></td><td><code>disabled</code></td><td><code>--xh-bg-muted</code></td><td>kbd 的 root 部件 background 覆盖槽。</td></tr><tr><td><code>--xh-kbd-border</code></td><td><code>root</code></td><td><code>border</code></td><td><code>default</code></td><td><code>--xh-material-soft-border</code></td><td>kbd 的 root 部件 border 覆盖槽。</td></tr><tr><td><code>--xh-kbd-fg</code></td><td><code>root</code></td><td><code>color</code></td><td><code>default</code></td><td><code>--xh-fg-default</code></td><td>kbd 的 root 部件 color 覆盖槽。</td></tr><tr><td><code>--xh-kbd-fg-disabled</code></td><td><code>root</code></td><td><code>color</code></td><td><code>disabled</code></td><td><code>--xh-fg-subtle</code></td><td>kbd 的 root 部件 color 覆盖槽。</td></tr><tr><td><code>--xh-kbd-fg-modifier</code></td><td><code>root</code></td><td><code>color</code></td><td><code>modifier</code></td><td><code>--xh-fg-muted</code></td><td>kbd 的 root 部件 color 覆盖槽。</td></tr><tr><td><code>--xh-kbd-font</code></td><td><code>root</code></td><td><code>font-family</code></td><td><code>default</code></td><td><code>--xh-font-family-mono</code></td><td>kbd 的 root 部件 font-family 覆盖槽。</td></tr><tr><td><code>--xh-kbd-font-size</code></td><td><code>root</code></td><td><code>font-size</code></td><td><code>default</code></td><td><code>--xh-_kbd-font-size</code></td><td>kbd 的 root 部件 font-size 覆盖槽。</td></tr><tr><td><code>--xh-kbd-font-weight</code></td><td><code>root</code></td><td><code>font-weight</code></td><td><code>default</code></td><td><code>--xh-font-weight-medium</code></td><td>kbd 的 root 部件 font-weight 覆盖槽。</td></tr><tr><td><code>--xh-kbd-min-w</code></td><td><code>root</code></td><td><code>min-inline-size</code></td><td><code>default</code></td><td><code>--xh-control-indicator-size</code></td><td>kbd 的 root 部件 min-inline-size 覆盖槽。</td></tr><tr><td><code>--xh-kbd-px</code></td><td><code>root</code></td><td><code>padding-inline</code></td><td><code>default</code></td><td><code>--xh-_kbd-px</code></td><td>kbd 的 root 部件 padding-inline 覆盖槽。</td></tr><tr><td><code>--xh-kbd-py</code></td><td><code>root</code></td><td><code>padding-block</code></td><td><code>default</code></td><td><code>--xh-space-0_5</code></td><td>kbd 的 root 部件 padding-block 覆盖槽。</td></tr><tr><td><code>--xh-kbd-radius</code></td><td><code>root</code></td><td><code>border-radius</code></td><td><code>default</code></td><td><code>--xh-shape-inset</code></td><td>kbd 的 root 部件 border-radius 覆盖槽。</td></tr><tr><td><code>--xh-kbd-shadow</code></td><td><code>root</code></td><td><code>box-shadow</code></td><td><code>default</code></td><td><code>--xh-stroke-thin</code></td><td>kbd 的 root 部件 box-shadow 覆盖槽。</td></tr><tr><td><code>--xh-kbd-shadow-pressed</code></td><td><code>root</code></td><td><code>box-shadow</code></td><td><code>active</code><br><code>disabled</code><br><code>is(button, a[href], [role=&#39;button&#39;], [role=&#39;menuitem&#39;], [role=&#39;option&#39;])</code><br><code>not([data-disabled])</code><br><code>not([disabled], [aria-disabled=&#39;true&#39;])</code><br><code>pressed</code></td><td><code>--xh-stroke-thin</code></td><td>kbd 的 root 部件 box-shadow 覆盖槽。</td></tr></tbody></table><h2 id="动效" tabindex="-1">动效 <a class="header-anchor" href="#动效" aria-label="Permalink to &quot;动效&quot;">​</a></h2><p><code>background-color</code> · <code>border-color</code> · <code>box-shadow</code> · <code>color</code> · <code>translate</code> 走 <code>transition</code> 过渡。时长与缓动读<a href="./../guide/motion">动效令牌</a>，改令牌即改全局节奏。</p><p>系统开启减弱动效时由令牌层统一收敛，皮肤不另作判断。</p><h2 id="rtl" tabindex="-1">RTL <a class="header-anchor" href="#rtl" aria-label="Permalink to &quot;RTL&quot;">​</a></h2><p>皮肤用逻辑属性排布（<code>inline-start</code> 一族），<code>dir=&quot;rtl&quot;</code> 下自动镜像。</p><h2 id="组合" tabindex="-1">组合 <a class="header-anchor" href="#组合" aria-label="Permalink to &quot;组合&quot;">​</a></h2><ul><li>与按钮、菜单条目或说明文字并排。</li><li>多枚键必须使用 KbdGroup，不要手写多个 <code>kbd</code> 再让读屏逐枚重复。</li></ul><h2 id="最佳实践" tabindex="-1">最佳实践 <a class="header-anchor" href="#最佳实践" aria-label="Permalink to &quot;最佳实践&quot;">​</a></h2><ul><li>跨平台快捷键写 <code>Mod</code>，不要把 Ctrl 或 Meta 写死。</li><li>只有动作真实触发期间才设置 <code>pressed</code>。</li></ul><h2 id="反模式" tabindex="-1">反模式 <a class="header-anchor" href="#反模式" aria-label="Permalink to &quot;反模式&quot;">​</a></h2><ul><li>用键帽替代实际按钮或菜单项。</li><li>给纯展示 Kbd 安装键盘监听。</li></ul>',44))])}const P=i(h,[["render",p]]);export{q as __pageData,P as default};
